using System.Text;
using Mono.Cecil;

namespace BEngine.Editor;

/// <summary>Registers the exact static Host boundary independently of linker-rewritten references.</summary>
internal static class PlayerHostAssemblyBootstrap
{
    internal static string Write(IEnumerable<string> assemblyPaths, string sourcePath, bool includeTextBindings,
        bool includeSkiaBindings = true, byte[]? startupLogoPng = null, string splashBackground = "#10161A")
    {
        var anchors = new SortedDictionary<string, string>(StringComparer.Ordinal);
        var initializerOwners = new Dictionary<string, string[]>(StringComparer.Ordinal);
        foreach (var path in assemblyPaths.Where(File.Exists).Distinct(StringComparer.OrdinalIgnoreCase))
        {
            using var assembly = AssemblyDefinition.ReadAssembly(path);
            var name = assembly.Name.Name;
            if (!DynamicManagedCodeTrimmerDescriptor.HostAssemblyAnchors.TryGetValue(name, out var anchor) ||
                !includeTextBindings && (name is "SkiaSharp" or "SkiaSharp.HarfBuzz" or "HarfBuzzSharp") ||
                !includeSkiaBindings && (name is "SkiaSharp" or "SkiaSharp.HarfBuzz"))
                continue;
            var type = assembly.MainModule.GetType(anchor);
            if (type is not { IsPublic: true, HasGenericParameters: false })
                throw new InvalidDataException($"Static Host assembly '{name}' is missing its public registration anchor '{anchor}'.");
            anchors[name] = anchor;
            initializerOwners[name] = EnumerateTypes(assembly.MainModule.Types)
                .Where(static candidate => candidate.Methods.Any(static method =>
                    method.IsStatic && method.CustomAttributes.Any(static attribute =>
                        attribute.AttributeType.FullName == "BEngine.RuntimeInitializeOnLoadMethodAttribute")))
                .Select(static candidate => candidate.FullName.Replace('/', '+'))
                .Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray();
        }

        var source = new StringBuilder("// Generated by the BEngine Player build pipeline.\n" +
            "internal static partial class BEngineStaticHostBootstrap\n{\n" +
            "    [System.Runtime.CompilerServices.ModuleInitializer]\n" +
            "    [System.Diagnostics.CodeAnalysis.SuppressMessage(\"Usage\", \"CA2255\")]\n" +
            "    internal static void Initialize()\n    {\n" +
            "        var assemblies = new global::System.Collections.Generic.Dictionary<string, global::System.Reflection.Assembly>(global::System.StringComparer.OrdinalIgnoreCase)\n        {\n");
        foreach (var (name, anchor) in anchors)
            source.Append("            [\"").Append(name).Append("\"] = typeof(global::")
                .Append(anchor).Append(").Assembly,\n");
        source.Append("        };\n" +
            "        foreach (var assembly in assemblies.Values)\n" +
            "            global::BEngine.HotUpdate.ManagedCodeHostAssemblies.Register(assembly);\n" +
            "        var pending = new global::System.Collections.Generic.HashSet<string>(assemblies.Keys, global::System.StringComparer.OrdinalIgnoreCase);\n" +
            "        foreach (var name in assemblies.Keys) InitializeHost(name);\n");
        // Register after module constructors, so the platform defaults exist before
        // RuntimeTypeCache initializes. Strings do not root otherwise trimmed types;
        // the normal post-linker type inventory remains authoritative at runtime.
        foreach (var name in anchors.Keys)
        {
            source.Append("        global::BEngine.RuntimeTypeCache.RegisterRuntimeInitializerOwners(assemblies[")
                .Append(System.Text.Json.JsonSerializer.Serialize(name)).Append("], new string[] { ")
                .AppendJoin(", ", initializerOwners[name].Select(static owner => System.Text.Json.JsonSerializer.Serialize(owner)))
                .Append(" });\n");
        }
        if (startupLogoPng is { Length: > 0 })
            source.Append("        global::BEngine.Player.PlayerStartupEnvironment.Configure(")
                .Append(System.Text.Json.JsonSerializer.Serialize(Convert.ToBase64String(startupLogoPng)))
                .Append(", ").Append(System.Text.Json.JsonSerializer.Serialize(splashBackground)).Append(");\n");
        source.Append("        ApplyPrecompiledInitializerHints();\n" +
            "        void InitializeHost(string name)\n        {\n" +
            "            if (!pending.Remove(name)) return;\n" +
            "            var assembly = assemblies[name];\n" +
            "            foreach (var reference in assembly.GetReferencedAssemblies())\n" +
            "                if (reference.Name is { } dependency && assemblies.ContainsKey(dependency))\n" +
            "                    InitializeHost(dependency);\n" +
            "            global::System.Runtime.CompilerServices.RuntimeHelpers.RunModuleConstructor(assembly.ManifestModule.ModuleHandle);\n" +
            "        }\n    }\n" +
            "    static partial void ApplyPrecompiledInitializerHints();\n}\n");
        Directory.CreateDirectory(Path.GetDirectoryName(sourcePath)!);
        File.WriteAllText(sourcePath, source.ToString(), new UTF8Encoding(false));
        return sourcePath;
    }

    private static IEnumerable<TypeDefinition> EnumerateTypes(IEnumerable<TypeDefinition> types)
    {
        foreach (var type in types)
        {
            yield return type;
            foreach (var nested in EnumerateTypes(type.NestedTypes)) yield return nested;
        }
    }
}
